   313→  private static List<String> extractList(JsonPathCache cache, JsonBranch branch) {
   314→    List<XmlFieldInstance> instances = cache.get(branch.getJsonPath());
   315→    List<String> values = new ArrayList<>();
   316→    if (instances != null)
   317→      for (XmlFieldInstance instance : instances)
   318→        values.add(instance.getValue());
   319→    return values;
   320→  }
   321→
   322→  private static String extractFirst(JsonPathCache cache, JsonBranch branch) {
   323→    List<String> list = extractList(cache, branch);
   324→    if (!list.isEmpty())
   325→      return list.get(0);
   326→    return null;
   327→  }
