   403→  public static Record createRecordFromMarcline(List<MarclineLine> lines) {
   404→    Record marc4jRecord = new RecordImpl();
   405→    for (MarclineLine line : lines) {
   406→      if (line.isLeader()) {
   407→        try {
   408→          marc4jRecord.setLeader(new LeaderImpl(line.getContent()));
   409→        } catch (StringIndexOutOfBoundsException e) {
   410→          logger.severe("Error at creating leader: " + e.getMessage());
   411→        }
   412→      } else if (line.isNumericTag()) {
   413→        if (line.isControlField()) {
   414→          marc4jRecord.addVariableField(new ControlFieldImpl(line.getTag(), line.getContent()));
   415→        } else {
   416→          var df = new DataFieldImpl(line.getTag(), line.getInd1().charAt(0), line.getInd2().charAt(0));
   417→          for (String[] pair : line.parseSubfields()) {
   418→            if (pair.length == 2 && pair[0] != null && pair[1] != null) {
   419→              df.addSubfield(new SubfieldImpl(pair[0].charAt(0), pair[1]));
   420→            } else {
   421→              logger.warning(String.format(
   422→                "parse error in record #%s) tag %s: '%s'",
   423→                line.getRecordID(), line.getTag(), line.getRawContent()
   424→              ));
   425→            }
   426→          }
   427→          marc4jRecord.addVariableField(df);
   428→        }
   429→      }
   430→    }
   431→    return marc4jRecord;
   432→  }
