   465→  public static Record createRecordFromPica(List<PicaLine> lines,
   466→                                            String idField,
   467→                                            String idCode,
   468→                                            PicaSchemaManager schema) {
   469→    Record marc4jRecord = new RecordImpl();
   470→    String id = null;
   471→    for (PicaLine line : lines) {
   472→      // String tag = schema.containsKey(line.getQualifiedTag()) ? line.getQualifiedTag() : line.getTag();
   473→      DataFieldImpl df = new DataFieldImpl(line.getQualifiedTag(), ' ', ' ');
   474→      for (PicaSubfield picaSubfield : line.getSubfields()) {
   475→        df.addSubfield(new SubfieldImpl(picaSubfield.getCode().charAt(0), picaSubfield.getValue()));
   476→        if (line.getTag().equals(idField) && picaSubfield.getCode().equals(idCode))
   477→          id = picaSubfield.getValue();
   478→      }
   479→      marc4jRecord.addVariableField(df);
   480→    }
   481→    if (id != null)
   482→      marc4jRecord.addVariableField(new ControlFieldImpl("001", id));
   483→    return marc4jRecord;
   484→  }
   485→}
